<?php use App\Core\Csrf; use App\Core\View; ?>
<div class="page-head"><div><h1><?= View::e($assignment['exam_title']) ?></h1><p><?= View::e($assignment['student_name']) ?> · <?= View::e($assignment['student_no']) ?> · 提交于 <?= View::e($assignment['submitted_at']) ?></p></div><a class="btn" href="/admin/grading">返回列表</a></div>
<form method="post"><?= Csrf::field() ?><?php foreach($questions as$q):?><article class="card question-card"><div class="question-number">第 <?= $q['display_order'] ?> 题 · <?= $q['question_type']==='practical'?'实践题':'主观题' ?> · 满分 <?= View::e($q['score']) ?></div><h3><?= View::e($q['title']) ?></h3><div class="prompt"><?= View::e($q['prompt']) ?></div><?php if($q['target_url']):?><p><a href="<?= View::e($q['target_url']) ?>" target="_blank" rel="noopener noreferrer">打开靶场网址</a></p><?php endif;?><div class="grid grid-2 top-gap"><div><h4>学生答案</h4><div class="answer-reference"><?= View::e($q['answer_text']?:'（未填写）') ?></div><?php if(!empty($uploads[$q['answer_id']])):?><div class="evidence-grid top-gap"><?php foreach($uploads[$q['answer_id']]as$u):?><a class="evidence" href="/evidence/<?= $u['id'] ?>" target="_blank"><img src="/evidence/<?= $u['id'] ?>" alt="实践截图"></a><?php endforeach;?></div><?php endif;?></div><div><h4>参考答案</h4><div class="answer-reference"><?= View::e($q['reference_answer']) ?></div></div></div><div class="form-grid top-gap"><div class="field"><label>得分（0～<?= View::e($q['score']) ?>）</label><input type="number" name="score[<?= $q['id'] ?>]" min="0" max="<?= View::e($q['score']) ?>" step="0.5" value="<?= View::e($q['answer_score']??0) ?>"></div><div class="field"><label>复核状态</label><select name="review[<?= $q['id'] ?>]"><option value="0">已评分</option><option value="1" <?= $q['review_status']==='review'?'selected':'' ?>>待复核</option></select></div><div class="field full"><label>逐题评语</label><textarea name="feedback[<?= $q['id'] ?>]"><?= View::e($q['feedback']??'') ?></textarea></div></div></article><?php endforeach;?><section class="card"><div class="field"><label>总评</label><textarea name="general_feedback"><?= View::e($assignment['general_feedback']??'') ?></textarea></div></section><div class="sticky-actions"><span class="muted">分数以 0.5 分为步进，不能超过题目满分。</span><button class="btn btn-primary">保存全部评分</button></div></form>

